from itertools import combinations

def solve_golomb_ruler():
    # We need 8 marks: x[0]=0, x[1]=2, x[2], ..., x[7]
    # All pairwise distances must be unique

    # Let's use backtracking
    marks = [0, 2]  # Fixed values

    def is_valid(new_mark, current_marks):
        # Check all pairwise distances with the new mark
        distances = set()
        for m in current_marks:
            d = new_mark - m
            if d <= 0:
                return False
            if d in distances:
                return False
            distances.add(d)

        # Check if any of these distances already exist in current marks
        existing_distances = set()
        for i in range(len(current_marks)):
            for j in range(i+1, len(current_marks)):
                existing_distances.add(current_marks[j] - current_marks[i])

        for d in distances:
            if d in existing_distances:
                return False

        return True

    def get_all_distances(marks):
        distances = set()
        for i in range(len(marks)):
            for j in range(i+1, len(marks)):
                distances.add(marks[j] - marks[i])
        return distances

    def backtrack(current_marks, next_val):
        if len(current_marks) == 8:
            return current_marks[:]

        # Try values starting from next_val
        # Upper bound: optimal Golomb ruler with 8 marks has length 34
        # Let's try up to 50 to be safe
        for val in range(next_val, 50):
            if is_valid(val, current_marks):
                current_marks.append(val)
                result = backtrack(current_marks, val + 1)
                if result:
                    return result
                current_marks.pop()

        return None

    result = backtrack(marks, 3)
    return result

